import{_ as a,o as r,c as d,aO as e}from"./chunks/framework.BFrk9dwu.js";const b=JSON.parse('{"title":"RAG","description":"","frontmatter":{"date":"2026-11-27T11:05:42.000Z","title":"RAG","sidebarSort":5,"categories":["ai"],"permalink":"/pages/564591"},"headers":[],"relativePath":"ai/03.RAG/index.md","filePath":"ai/03.RAG/index.md","lastUpdated":1795780631000}'),o={name:"ai/03.RAG/index.md"};function i(n,t,l,h,s,p){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="rag" tabindex="-1">RAG <a class="header-anchor" href="#rag" aria-label="Permalink to &quot;RAG&quot;">​</a></h1><h2 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h2><p>RAG（Retrieval-Augmented Generation，检索增强生成）就是<strong>先去你的资料里找几段相关内容，再把这几段塞进提示词，让模型据此回答</strong>。</p><p>它解决的不是「模型不够聪明」，而是「模型没见过你的文档」。模型权重里没有公司制度、没有你刚写的笔记，硬问只能得到编造。</p><h2 id="有什么用" tabindex="-1">有什么用 <a class="header-anchor" href="#有什么用" aria-label="Permalink to &quot;有什么用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>直接问模型</th><th>用 RAG</th></tr></thead><tbody><tr><td>内部制度、流程文档</td><td>编造条款</td><td>引用原文段落</td></tr><tr><td>几十万字的项目资料</td><td>塞不进上下文</td><td>每次只取相关几段</td></tr><tr><td>需要标注出处</td><td>无法给出</td><td>附文件名与位置</td></tr></tbody></table><p>核心收益是<strong>可验证</strong>：答案旁边能挂来源，对不上就是检索错了，而不是模型疯了。</p><h2 id="一条完整链路" tabindex="-1">一条完整链路 <a class="header-anchor" href="#一条完整链路" aria-label="Permalink to &quot;一条完整链路&quot;">​</a></h2><p>五个环节，任一环做差，最后都表现为「答得不准」：</p><ol><li><strong>切分</strong>：把文档切成一段段（chunk），保留语义完整</li><li><strong>向量化</strong>：用 embedding 模型把每段变成向量，存进向量库</li><li><strong>检索</strong>：把问题也向量化，按相似度取 top-k</li><li><strong>拼上下文</strong>：把命中的段落拼进提示词，附编号</li><li><strong>生成</strong>：要求模型只依据给定材料回答，并标注引用编号</li></ol><h2 id="关键参数" tabindex="-1">关键参数 <a class="header-anchor" href="#关键参数" aria-label="Permalink to &quot;关键参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>作用</th><th>起步值</th></tr></thead><tbody><tr><td>chunk size</td><td>单段长度，太小失上下文，太大稀释相关度</td><td>400–800 字</td></tr><tr><td>chunk overlap</td><td>相邻段重叠，防止句子被切断</td><td>10%–20%</td></tr><tr><td>top_k</td><td>取回几段</td><td>3–5</td></tr><tr><td>相似度阈值</td><td>低于阈值视为没找到</td><td>按模型定，先看分布再定</td></tr></tbody></table><p>短文档问答可以把整篇塞进上下文，不做检索反而更准——<strong>切分本身就会损失信息</strong>。</p><h2 id="别只靠向量检索" tabindex="-1">别只靠向量检索 <a class="header-anchor" href="#别只靠向量检索" aria-label="Permalink to &quot;别只靠向量检索&quot;">​</a></h2><p>纯向量检索对<strong>精确字符串</strong>不敏感：编号、型号、人名、错误码，关键词匹配反而更准。</p><table tabindex="0"><thead><tr><th>方案</th><th>强在哪</th></tr></thead><tbody><tr><td>向量检索</td><td>语义相近，换个说法也能找到</td></tr><tr><td>关键词检索（BM25）</td><td>精确词命中，编号、专有名词</td></tr><tr><td>混合检索 + 重排</td><td>两路召回后统一排序，效果最好，成本略高</td></tr></tbody></table><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><p><strong>现象：命中的段落看着相关，答案还是错。</strong> 原因：切分把条件和结论分到了两段。 解法：按标题层级切，段落带上级标题，保证上下文自足。</p><p><strong>现象：问「最新版怎么规定」，答的是旧版本。</strong> 原因：检索没有时间过滤，旧文档相似度更高。 解法：元数据带上日期和版本，检索时加过滤条件。</p><p><strong>现象：模型把检索内容当成自己的知识扩写。</strong> 原因：提示词没限制「只依据材料」。 解法：明确「材料中没有的信息，回答『资料未提及』」，并要求标注引用编号。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><ol><li>RAG 解决的是「模型没见过你的资料」，不是让它变聪明</li><li>链路五步，答不准先查切分和检索，别先怪模型</li><li>chunk 400–800 字、overlap 10%–20%、top_k 3–5 是稳妥起点</li><li>编号、型号这类精确词，必须配关键词检索，纯向量会漏</li><li>提示词必须写「只依据材料回答，没有就说未提及」，并要求标注引用</li><li>短文档别硬上 RAG，整篇塞进上下文往往更准</li></ol>',22)])])}const g=a(o,[["render",i]]);export{b as __pageData,g as default};
